#!/usr/bin/env python3
"""Adversarial content-preservation check for PROGRESS/GLOSSARY canonicalization.

For every original per-branch file, every normalized non-blank line must appear
in the corresponding canonical file, except for two whitelisted intentional edits.
Also validates the canonical PROGRESS header structure.
"""
import re
import sys
from pathlib import Path

BASE = Path("/private/tmp/claude-501/-Users-brandonlee-development-repos-products-"
             "HFT-Trading-Practice-Repo/cf65b35f-8909-4987-b7e3-b3900eecfd2a/"
             "scratchpad/merge-fix")


def norm_lines(path: Path) -> list[tuple[int, str]]:
    """Return (lineno, stripped) for every non-blank line in path."""
    out = []
    for i, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), 1):
        s = raw.strip()
        if s:
            out.append((i, s))
    return out


# --- Whitelist ---------------------------------------------------------------
# 1. mm/vhdl "Next suggested" line variant with "(perf/03)" deliberately replaced
#    by main's variant without it.
WL_PERF03 = "`/teach` the incremental best-index optimization when it lands (perf/03), or the"

# 2. The five-line "Note on numbering" paragraph in PROGRESS.0008.md (deliberately
#    rewritten in canonical). Identified structurally: contiguous non-blank lines
#    starting at the line beginning "**Note on numbering:**" in PROGRESS.0008.md.
def note_on_numbering_lines(path: Path) -> set[str]:
    lines = path.read_text(encoding="utf-8").splitlines()
    out: set[str] = set()
    in_para = False
    for raw in lines:
        s = raw.strip()
        if s.startswith("**Note on numbering:**"):
            in_para = True
        if in_para:
            if not s:
                break
            out.add(s)
    return out


def check_file(orig: Path, canon: Path, whitelist: set[str]) -> list[tuple[int, str]]:
    canon_set = {s for _, s in norm_lines(canon)}
    missing = []
    for lineno, s in norm_lines(orig):
        if s in canon_set:
            continue
        if s in whitelist:
            continue
        missing.append((lineno, s))
    return missing


def main() -> int:
    failures = 0

    note_wl = note_on_numbering_lines(BASE / "PROGRESS.0008.md")
    print(f"Whitelisted Note-on-numbering paragraph lines ({len(note_wl)}):")
    for s in sorted(note_wl):
        print(f"   WL: {s}")
    print(f"Whitelisted perf/03 variant line:\n   WL: {WL_PERF03}\n")

    progress_checks = {
        "PROGRESS.main.md": set(),
        "PROGRESS.mm.md": {WL_PERF03},
        "PROGRESS.vhdl.md": {WL_PERF03},
        "PROGRESS.0008.md": note_wl,
    }
    canon_p = BASE / "PROGRESS.canonical.md"
    for name, wl in progress_checks.items():
        missing = check_file(BASE / name, canon_p, wl)
        if missing:
            failures += len(missing)
            print(f"MISSING from PROGRESS.canonical.md (source {name}):")
            for lineno, s in missing:
                print(f"   {name}:{lineno}: {s}")
        else:
            print(f"OK: all content lines of {name} present in canonical (whitelist applied: {len(wl)} distinct lines)")

    canon_g = BASE / "GLOSSARY.canonical.md"
    for name in ("GLOSSARY.main.md", "GLOSSARY.0008.md"):
        missing = check_file(BASE / name, canon_g, set())
        if missing:
            failures += len(missing)
            print(f"MISSING from GLOSSARY.canonical.md (source {name}):")
            for lineno, s in missing:
                print(f"   {name}:{lineno}: {s}")
        else:
            print(f"OK: all content lines of {name} present in canonical")

    # --- Structure check on canonical PROGRESS -------------------------------
    text = canon_p.read_text(encoding="utf-8").splitlines()
    section = None
    covered_h3, backlog_h3 = [], []
    for raw in text:
        s = raw.strip()
        if s.startswith("## "):
            section = s[3:].strip()
        elif s.startswith("### "):
            h = s[4:].strip()
            if section == "Covered":
                covered_h3.append(h)
            elif section == "Backlog":
                backlog_h3.append(h)
            else:
                print(f"STRUCTURE FAIL: h3 outside Covered/Backlog: {h!r} (section={section!r})")
                failures += 1

    expected_covered_prefixes = ["0001", "0006", "0008"]
    expected_backlog = [
        r"^0003 ",
        r"^0004 ",
        r"^0005 ",
        r"^Pending /teach target .*[Ll]ook-ahead",
        r"^Pending /teach targets .*A-S market making \+ queue priority",
        r"^0007 ",
    ]

    print("\nCanonical PROGRESS structure:")
    print(f"  Covered h3s: {covered_h3}")
    print(f"  Backlog h3s: {backlog_h3}")

    if len(covered_h3) != 3 or any(
        not h.startswith(p) for h, p in zip(covered_h3, expected_covered_prefixes)
    ):
        print(f"STRUCTURE FAIL: Covered headers != 0001,0006,0008 in order")
        failures += 1
    else:
        print("  OK: Covered = 0001, 0006, 0008 in order")

    if len(backlog_h3) != 6 or any(
        not re.search(pat, h.replace("—", " ").replace("  ", " "))
        and not re.search(pat, h)
        for h, pat in zip(backlog_h3, expected_backlog)
    ):
        print("STRUCTURE FAIL: Backlog headers do not match expected order/content")
        failures += 1
    else:
        print("  OK: Backlog = 0003, 0004, 0005, look-ahead pending, A-S/queue pending, 0007 in order")

    print(f"\n{'FAIL' if failures else 'PASS'}: {failures} problem(s) found")
    return 1 if failures else 0


if __name__ == "__main__":
    sys.exit(main())
